targets.query:
from(bucket: "telemetry")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "telemetry" and r._field == "ts")
  |> map(fn: (r) => ({
       _time: r._time,
       _value: float(v: int(v: r._time) - int(v: time(v: r._value))) / 1000000000.0,
     }))
  |> aggregateWindow(every: 30s, fn: mean, createEmpty: false)

from(bucket: "telemetry")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
